"""Local handover review and bounded graph impact tools."""
import html,json
from .handover import build_handover

def handover_panel(report):
    esc=lambda s:html.escape(str(s),quote=True)
    data=report.get('handover') or build_handover(report)
    def links(indices):return ' · '.join('<a class="evidence-link" href="#finding-'+str(i)+'">'+esc(report['findings'][i]['evidence']['file'])+':'+str(report['findings'][i]['evidence'].get('line',1))+'</a>' for i in indices[:8])+(' · '+str(len(indices)-8)+' more references in JSON' if len(indices)>8 else '')
    rows=''.join('<tr><td>'+esc(c['kind'].replace('_',' '))+'</td><td>'+esc(c['name'])+'</td><td>'+('Name found in example/template' if c.get('template_name_found') else 'Required value/setup unconfirmed')+'</td><td>'+links(c['evidence_indices'])+'</td></tr>' for c in data['clues'])
    tasks=''.join('<article class="handover-task" data-task="'+esc(t['id'])+'"><h3>'+esc(t['title'])+'</h3><p>'+esc(t['check'])+'</p><p>'+links(t['evidence_indices'])+'</p><label>Status <select class="task-status"><option>Not checked</option><option>Needs information</option><option>Blocked</option><option>Verified by reviewer</option></select></label><label>Owner <input class="task-owner" maxlength="100"></label><label>Notes / verification reference <textarea class="task-notes" rows="2" maxlength="2000"></textarea></label></article>' for t in data['tasks'])
    return '<h2>Prepare a practical handover</h2><button data-guide="tab-readiness">Review linked sandbox tests for this ZIP</button><p>This checklist turns findings into questions to resolve. Reviewer statuses are your annotations, not automated proof. Notes stay in page memory and are excluded from AI requests. Do not enter credentials.</p><nav><button id="handover-export">Save handover checklist (JSON)</button><button id="handover-text">Save readable handover notes</button></nav><label>Restore saved checklist (JSON, maximum 1 MiB) <input id="handover-import" type="file" accept=".json,application/json"></label><button id="handover-apply" hidden>Replace checklist with reviewed saved notes</button><pre id="handover-preview"></pre><p id="handover-status" role="status">Save this checklist before clearing or closing. Standard HTML/JSON report exports do not preserve your review notes. A handover pack includes them only when you select Include my checklist annotations. To resume received notes here, choose the accompanying checklist JSON, review the fingerprint preview, then press Replace. You can restore inside a saved report without re-analysis; nothing is autosaved.</p><details><summary>Setup clues: configuration names, scripts and runtime constraints</summary><p>'+esc(data['scope'])+'</p><p>'+str(data['omitted_clues'])+' additional clues omitted.</p><div class="scroll"><table><tr><th>Type</th><th>Name / constraint</th><th>Assessment</th><th>Evidence</th></tr>'+rows+'</table></div></details>'+tasks

IMPACT_PANEL='<h2>Explore possible change impact</h2><p>Choose a file to explore its recorded code nodes and nearby upstream and downstream references. File association comes from the supported source reader; it does not establish runtime behavior. These are bounded static candidates, not proven breakages or a complete impact analysis. Dynamic links, missing code and shared-name inference can hide or overstate relationships.</p><label for="impact-file">File to investigate</label><select id="impact-file"></select><p id="impact-summary" role="status"></p><div id="impact-results"></div>'
SCRIPT=r"""
(()=>{
const report=JSON.parse(document.querySelector('#report-data').textContent),graph=report.feature_map||{nodes:[],edges:[]},$=s=>document.querySelector(s);
$('#handover-export').onclick=()=>{const tasks=[...document.querySelectorAll('.handover-task')].map(el=>({id:el.dataset.task,status:el.querySelector('.task-status').value,owner:el.querySelector('.task-owner').value,notes:el.querySelector('.task-notes').value}));download(JSON.stringify({format:'reversium-handover',version:2,archive_sha256:report.archive_sha256||null,archive_name:report.archive_name||'',scope:'Reviewer annotations, not automated runtime verification.',tasks},null,2),'application/json','reversium-handover.json');$('#handover-status').textContent='Checklist saved locally. Store it with the matching report and ZIP delivery.'};
$('#handover-text').onclick=()=>{const notes=[...document.querySelectorAll('.handover-task')].map(el=>el.querySelector('h3').textContent+'\nStatus: '+el.querySelector('.task-status').value+'\nOwner: '+el.querySelector('.task-owner').value+'\nNotes: '+el.querySelector('.task-notes').value+'\n');download('Reversium handover review\nPackage: '+(report.archive_name||'Uploaded package')+'\nReviewer annotations, not automated verification.\n\n'+notes.join('\n'),'text/plain','reversium-handover.txt')};
const picker=$('#impact-file'),nodes=new Map(graph.nodes.map(n=>[n.id,n])),codeNodes=graph.nodes.filter(n=>['module','handler','helper','feature'].includes(n.kind)),origins=n=>n.file?[n.file]:[],files=[...new Set(codeNodes.flatMap(origins))].sort();
for(const file of files){const option=document.createElement('option');option.value=file;option.textContent=file;picker.append(option)}
function draw(){const file=picker.value,starts=new Set(codeNodes.filter(n=>origins(n).includes(file)).map(n=>n.id)),area=$('#impact-results');area.replaceChildren();const allIds=new Set();
for(const direction of ['Upstream references','Downstream references']){const seen=new Set(starts),queue=[...starts].map(id=>[id,0]),found=[];let visits=0,limited=false;
while(queue.length){const [id,depth]=queue.shift();if(depth>=3)continue;for(const edge of graph.edges){if(++visits>60000){limited=true;break}const target=direction==='Upstream references'?(edge.target===id?edge.source:null):(edge.source===id?edge.target:null);if(!target||seen.has(target))continue;seen.add(target);found.push({node:nodes.get(target),edge,depth:depth+1});queue.push([target,depth+1]);if(found.length>=120){limited=true;break}}if(limited)break}
const h=document.createElement('h3');h.textContent=direction;area.append(h);if(!found.length){const p=document.createElement('p');p.textContent='No connected candidates found within this view. This does not prove no dependencies.';area.append(p)}for(const {node,edge,depth} of found){if(!node)continue;const p=document.createElement('p');p.append(document.createTextNode((node.label||node.id)+' — '+(origins(node)[0]||'external/data reference')+' · '+edge.label+' · '+edge.confidence+' · '+depth+' hop(s) '));for(const i of (edge.evidence_indices||[]).slice(0,3)){const a=document.createElement('a');a.href='#finding-'+i;a.textContent='['+i+'] ';a.onclick=e=>{e.preventDefault();revealFinding(a.getAttribute('href'))};p.append(a)}area.append(p)}if(limited){const p=document.createElement('p');p.textContent='View bounded: additional candidates may be omitted.';area.append(p)}for(const entry of found)if(entry.node)allIds.add(entry.node.id);}
$('#impact-summary').textContent=files.length?allIds.size+' nearby candidate nodes. Maximum 3 hops, 120 candidates per direction and 60,000 edge checks per direction.':'No supported graph files available.';}
picker.onchange=draw;draw();
})();
"""
